16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.FiscalYear;
20	import org.springframework.samples.petclinic.util.Luhn;
21	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
22	import org.springframework.samples.petclinic.util.Sha256;
23	import org.springframework.samples.petclinic.util.Soundex;
24	
25	import jakarta.persistence.*;
26	import jakarta.validation.constraints.NotEmpty;
27	import jakarta.validation.constraints.Pattern;
28	
29	import java.time.LocalDate;
30	import java.util.*;
31	
32	/**
33	 * Simple JavaBean domain object representing an owner.
34	 *
35	 * @author Ken Krebs
36	 * @author Juergen Hoeller
37	 * @author Sam Brannen
38	 * @author Michael Isvy
39	 */
40	@Entity
41	@Table(name = "owners")
42	public class Owner extends Person {
43	    @Column(name = "title")
44	    private String title;
45	
46	    @Column(name = "address")
47	    @NotEmpty
48	    private String address;
49	
50	    @Column(name = "address_line1")
51	    private String addressLine1;
52	
53	    @Column(name = "address_line2")
54	    private String addressLine2;
55	
56	    @Column(name = "city")
57	    @NotEmpty
58	    private String city;
59	
60	    @Column(name = "postcode")
61	    private String postcode;
62	
63	    @Column(name = "telephone")
64	    @NotEmpty
65	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
66	    private String telephone;
67	
68	    @Column(name = "email")
69	    private String email;
70	
71	    @Column(name = "birth_date")
72	    private LocalDate birthDate;
73	
74	    @Column(name = "registration_date")
75	    private LocalDate registrationDate;
76	
77	    @Column(name = "customer_code")
78	    private String customerCode;
79	
80	    @Column(name = "household_id")
81	    private String householdId;
82	
83	    @Column(name = "namesake_count")
84	    private Integer namesakeCount;
85	
86	    @Column(name = "household_size")
87	    private Integer householdSize;
88	
89	    @Column(name = "membership_level_cap")
90	    private Integer membershipLevelCap;
91	
92	    @Column(name = "possible_duplicate")
93	    private Boolean possibleDuplicate;
94	
95	    @Column(name = "possible_duplicate_of")
96	    private Integer possibleDuplicateOf;
97	
98	    @Column(name = "deleted", nullable = false)
99	    private boolean deleted;
100	
101	    /**
102	     * Whether this owner was knowingly created into a shared household (the request declared shared
103	     * membership). A declared member is not treated as a suspected duplicate. Set per request and
104	     * never persisted.
105	     */
106	    @Transient
107	    private boolean declaredHouseholdMember;
108	
109	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
110	    private Set<Pet> pets;
111	
112	    /**
113	     * Resolve the registration date at creation time: default it to the server's
114	     * current date when none was supplied, and roll a weekend date forward to the
115	     * next business day so every value derived from it (such as the membership
116	     * number's year segment) uses the adjusted date.
117	     */
118	    @PrePersist
119	    private void resolveRegistrationDate() {
120	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
121	    }
122	
123	    public String getTitle() {
124	        return this.title;
125	    }
126	
127	    public void setTitle(String title) {
128	        this.title = title;
129	    }
130	
131	    /**
132	     * The owner's salutation: the {@link #title} followed by a space and the
133	     * {@linkplain #getLastName() last name} (e.g. {@code "DR Who"}), or just the
134	     * last name when no title is on file.
135	     */
136	    public String getSalutation() {
137	        if (this.title == null || this.title.isEmpty()) {
138	            return getLastName();
139	        }
140	        return this.title + " " + getLastName();
141	    }
142	
143	    public String getAddress() {
144	        return this.address;
145	    }
146	
147	    public void setAddress(String address) {
148	        this.address = address;
149	    }
150	
151	    public String getAddressLine1() {
152	        return this.addressLine1;
153	    }
154	
155	    public void setAddressLine1(String addressLine1) {
156	        this.addressLine1 = addressLine1;
157	    }
158	
159	    public String getAddressLine2() {
160	        return this.addressLine2;
161	    }
162	
163	    public void setAddressLine2(String addressLine2) {
164	        this.addressLine2 = addressLine2;
165	    }
166	
167	    public String getCity() {
168	        return this.city;
169	    }
170	
171	    public void setCity(String city) {
172	        this.city = city;
173	    }
174	
175	    public String getPostcode() {
176	        return this.postcode;
177	    }
178	
179	    public void setPostcode(String postcode) {
180	        this.postcode = postcode;
181	    }
182	
183	    /**
184	     * The owner's locality: the region component of its {@link #customerCode}
185	     * identity (see {@link CustomerCode}), or {@code null} when no customer code
186	     * is assigned. The region was derived from the owner's postcode and city when
187	     * the identity was minted, so the locality now follows the identity rather than
188	     * being recomputed from the current city and postcode.
189	     */
190	    public String getLocality() {
191	        return CustomerCode.regionOf(this.customerCode);
192	    }
193	
194	    /**
195	     * The owner's timezone: the IANA name for its {@linkplain #getLocality()
196	     * locality}, from the fixed region-to-timezone table (see
197	     * {@link RegionTimezone}), or {@code null} when the locality is absent or has
198	     * no known timezone.
199	     */
200	    public String getTimezone() {
201	        return RegionTimezone.zoneFor(getLocality());
202	    }
203	
204	    public String getTelephone() {
205	        return this.telephone;
206	    }
207	
208	    public void setTelephone(String telephone) {
209	        this.telephone = telephone;
210	    }
211	
212	    public String getEmail() {
213	        return this.email;
214	    }
215	
216	    public void setEmail(String email) {
217	        this.email = email;
218	    }
219	
220	    public LocalDate getBirthDate() {
221	        return this.birthDate;
222	    }
223	
224	    public void setBirthDate(LocalDate birthDate) {
225	        this.birthDate = birthDate;
226	    }
227	
228	    /**
229	     * The owner's {@link AgeBand age band} on the {@link #registrationDate}, derived
230	     * from the {@link #birthDate}, or {@code null} when no birth date is on file.
231	     */
232	    public AgeBand getAgeBand() {
233	        return AgeBand.on(this.birthDate, this.registrationDate);
234	    }
235	
236	    public LocalDate getRegistrationDate() {
237	        return this.registrationDate;
238	    }
239	
240	    public void setRegistrationDate(LocalDate registrationDate) {
241	        this.registrationDate = registrationDate;
242	    }
243	
244	    public String getCustomerCode() {
245	        return this.customerCode;
246	    }
247	
248	    public void setCustomerCode(String customerCode) {
249	        this.customerCode = customerCode;
250	    }
251	
252	    /**
253	     * The owner's current primary identifier: the {@link #getCustomerCode() customer code}.
254	     *
255	     * <p>Consumers such as audit events depend on "the primary identifier" through this single
256	     * accessor rather than on whichever field currently holds it, so when the customer code is
257	     * later unified into the member id only this method changes and the identifier the events
258	     * carry follows automatically.
259	     */
260	    public String getPrimaryIdentifier() {
261	        return getCustomerCode();
262	    }
263	
264	    /**
265	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
266	     * where {@code YY} is the two-digit segment of the {@linkplain #getFiscalYear()
267	     * fiscal year} of the {@link #registrationDate} (e.g. {@code "NSW-3F2A9C1D-M27"}
268	     * for a registration in fiscal year 2027). Derived from the owner's own fields.
269	     */
270	    public String getMembershipNumber() {
271	        if (this.customerCode == null || this.registrationDate == null) {
272	            return null;
273	        }
274	        return String.format("%s-M%02d", this.customerCode, FiscalYear.yearSegment(this.registrationDate));
275	    }
276	
277	    /**
278	     * The owner's fiscal year: the {@code 'FY<YY>'} label (e.g. {@code "FY27"}) of the
279	     * fiscal year the {@link #registrationDate} falls in, where a fiscal year starts on
280	     * 1 July and is numbered by the calendar year in which it ends (see
281	     * {@link FiscalYear}). {@code null} when no registration date is on file.
282	     */
283	    public String getFiscalYear() {
284	        return FiscalYear.label(this.registrationDate);
285	    }
286	
287	    /**
288	     * The Luhn check digit (0-9) computed over the digits of the
289	     * {@link #customerCode}, or {@code null} when no customer code is assigned.
290	     */
291	    public Integer getCheckDigit() {
292	        if (this.customerCode == null) {
293	            return null;
294	        }
295	        return Luhn.checkDigit(this.customerCode);
296	    }
297	
298	    public String getHouseholdId() {
299	        return this.householdId;
300	    }
301	
302	    public void setHouseholdId(String householdId) {
303	        this.householdId = householdId;
304	    }
305	
306	    /**
307	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
308	     * 64-character lower-case SHA-256 hex digest (see {@link org.springframework.samples.petclinic.util.Sha256})
309	     * of the normalized telephone, the lower-cased email (or an empty string when absent) and the
310	     * {@linkplain org.springframework.samples.petclinic.util.Soundex Soundex} code of the last name,
311	     * joined with {@code '|'}. Two owners are the same person only when their identity keys are
312	     * equal; because the telephone is part of the key, household members with different telephones
313	     * have different keys.
314	     */
315	    public String getIdentityKey() {
316	        String key = String.join("|",
317	            this.telephone == null ? "" : this.telephone,
318	            this.email == null ? "" : this.email.toLowerCase(Locale.ROOT),
319	            Soundex.encode(getLastName()));
320	        return Sha256.hex(key);
321	    }
322	
323	    /** Tenure, in elapsed fiscal years, at or beyond which an owner earns the tenure membership points. */
324	    private static final long TENURE_FISCAL_YEARS_FOR_POINTS = 1;
325	
326	    /** Household size at or above which an owner earns the household membership points. */
327	    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;
328	
329	    /**
330	     * The owner's membership points, a score derived from the owner's own
331	     * fields. Starts at {@code 0}, gains {@code 2} when a contact email is on
332	     * file, gains {@code 1} when the owner has no namesakes, gains {@code 2}
333	     * when the owner belongs to a household of {@value #HOUSEHOLD_SIZE_FOR_POINTS}
334	     * or more, and gains {@code 3} when the owner's {@link #getTenureFiscalYears()
335	     * tenure} reaches {@value #TENURE_FISCAL_YEARS_FOR_POINTS} or more elapsed fiscal years.
336	     */
337	    public Integer getMembershipPoints() {
338	        int points = 0;
339	        boolean hasEmail = this.email != null && !this.email.isEmpty();
340	        if (hasEmail) {
341	            points += 2;
342	        }
343	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
344	        if (noNamesakes) {
345	            points += 1;
346	        }
347	        boolean largeHousehold = this.householdSize != null && this.householdSize >= HOUSEHOLD_SIZE_FOR_POINTS;
348	        if (largeHousehold) {
349	            points += 2;
350	        }
351	        Long tenureFiscalYears = getTenureFiscalYears();
352	        if (tenureFiscalYears != null && tenureFiscalYears >= TENURE_FISCAL_YEARS_FOR_POINTS) {
353	            points += 3;
354	        }
355	        return points;
356	    }
357	
358	    /**
359	     * The owner's membership level, a number from 1 to 4 mapped from the owner's
360	     * {@link #getMembershipPoints() membership points}: {@code 1} for 0-1 points,
361	     * {@code 2} for 2-3, {@code 3} for 4-5 and {@code 4} for 6 or more.
362	     *
363	     * <p>The level is held down to the {@linkplain #getMembershipLevelCap()
364	     * household ceiling} when one applies, so a new owner never outranks its
365	     * household by more than one level.
366	     */
367	    public Integer getMembershipLevel() {
368	        int level = pointsToLevel(getMembershipPoints());
369	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
370	            return this.membershipLevelCap;
371	        }
372	        return level;
373	    }
374	
375	    private static int pointsToLevel(int points) {
376	        if (points <= 1) {
377	            return 1;
378	        }
379	        if (points <= 3) {
380	            return 2;
381	        }
382	        if (points <= 5) {
383	            return 3;
384	        }
385	        return 4;
386	    }
387	
388	    /**
389	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership
390	     * level}: one above the highest level among its household's existing members
391	     * when it was created, or {@code null} when no household member capped it.
392	     */
393	    public Integer getMembershipLevelCap() {
394	        return this.membershipLevelCap;
395	    }
396	
397	    public void setMembershipLevelCap(Integer membershipLevelCap) {
398	        this.membershipLevelCap = membershipLevelCap;
399	    }
400	
401	    /**
402	     * The owner's tenure: the number of whole fiscal years elapsed from the
403	     * {@link #registrationDate} to the server's current date — the count of 1 July
404	     * boundaries crossed between them (see {@link FiscalYear}), or {@code null} when no
405	     * registration date is on file. Zero while both dates fall in the same fiscal year,
406	     * and never negative for a registration date that is today or earlier.
407	     */
408	    public Long getTenureFiscalYears() {
409	        if (this.registrationDate == null) {
410	            return null;
411	        }
412	        return FiscalYear.elapsedYears(this.registrationDate, LocalDate.now());
413	    }
414	
415	    /**
416	     * The owner's preferred contact channel, derived from the fields on file:
417	     * {@code "EMAIL"} when a contact email is present, otherwise {@code "PHONE"}.
418	     */
419	    public String getContactPreference() {
420	        boolean hasEmail = this.email != null && !this.email.isEmpty();
421	        return hasEmail ? "EMAIL" : "PHONE";
422	    }
423	
424	    public Integer getNamesakeCount() {
425	        return this.namesakeCount;
426	    }
427	
428	    public void setNamesakeCount(Integer namesakeCount) {
429	        this.namesakeCount = namesakeCount;
430	    }
431	
432	    public Integer getHouseholdSize() {
433	        return this.householdSize;
434	    }
435	
436	    public void setHouseholdSize(Integer householdSize) {
437	        this.householdSize = householdSize;
438	    }
439	
440	    /**
441	     * Whether this owner, while not a declared household member, shares an existing owner's
442	     * last name and postcode but carries a different telephone. Determined once,
443	     * when the owner is created. A declared household member is never a suspected duplicate.
444	     */
445	    public Boolean getPossibleDuplicate() {
446	        return this.possibleDuplicate;
447	    }
448	
449	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
450	        this.possibleDuplicate = possibleDuplicate;
451	    }
452	
453	    /**
454	     * Whether this owner was knowingly created into a shared household. Such a declared member
455	     * bypasses the household-duplicate block and is not flagged as a suspected duplicate.
456	     */
457	    public boolean isDeclaredHouseholdMember() {
458	        return this.declaredHouseholdMember;
459	    }
460	
461	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
462	        this.declaredHouseholdMember = declaredHouseholdMember;
463	    }
464	
465	    /**
466	     * The id of the existing owner this owner possibly duplicates, or {@code null}
467	     * when it has no such match.
468	     */
469	    public Integer getPossibleDuplicateOf() {
470	        return this.possibleDuplicateOf;
471	    }
472	
473	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
474	        this.possibleDuplicateOf = possibleDuplicateOf;
475	    }
476	
477	    /**
478	     * Whether this owner has been soft-deleted: {@code DELETE /api/owners/{id}} flags the owner
479	     * deleted and retains the row rather than removing it. A soft-deleted owner is still returned by
480	     * a read, but is ignored by the create endpoint's duplicate and identity checks. A newly created
481	     * owner is not deleted.
482	     */
483	    public boolean isDeleted() {
484	        return this.deleted;
485	    }
486	
487	    public void setDeleted(boolean deleted) {
488	        this.deleted = deleted;
489	    }
490	
491	    protected Set<Pet> getPetsInternal() {
492	        if (this.pets == null) {
493	            this.pets = new HashSet<>();
494	        }
495	        return this.pets;
496	    }
497	
498	    protected void setPetsInternal(Set<Pet> pets) {
499	        this.pets = pets;
500	    }
501	
502	    public List<Pet> getPets() {
503	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
504	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
505	        return Collections.unmodifiableList(sortedPets);
506	    }
507	
508	    public void setPets(List<Pet> pets) {
509	        this.pets = new HashSet<>(pets);
510	    }
511	
512	    public void addPet(Pet pet) {
513	        getPetsInternal().add(pet);
514	        pet.setOwner(this);
515	    }
516	
517	    /**
518	     * Return the Pet with the given name, or null if none found for this Owner.
519	     *
520	     * @param name to test
521	     * @return true if pet name is already in use
522	     */
523	    public Pet getPet(String name) {
524	        return getPet(name, false);
525	    }
526	
527	    /**
528	     * Return the Pet with the given name, or null if none found for this Owner.
529	     *
530	     * @param name to test
531	     * @return true if pet name is already in use
532	     */
533	    public Pet getPet(String name, boolean ignoreNew) {
534	        name = name.toLowerCase();
535	        for (Pet pet : getPetsInternal()) {
536	            if (!ignoreNew || !pet.isNew()) {
537	                String compName = pet.getName();
538	                compName = compName.toLowerCase();
539	                if (compName.equals(name)) {
540	                    return pet;
541	                }
542	            }
543	        }
544	        return null;
545	    }
546	
547	    public Pet getPet(Integer petId) {
548	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
549	    }
550	
551	    @Override
552	    public String toString() {
553	        return new ToStringCreator(this)
554	
555	            .append("id", this.getId())
556	            .append("new", this.isNew())
557	            .append("lastName", this.getLastName())
558	            .append("firstName", this.getFirstName())
559	            .append("address", this.address)
560	            .append("city", this.city)
561	            .append("telephone", this.telephone)
562	            .append("email", this.email)
563	            .toString();
564	    }
565	}
